<?php
$uid = (int)$u['id'];
handle('rec_add', function () use ($uid) { $k = $_POST['kind'] ?? ''; if (!in_array($k, ['income', 'bill', 'subscription', 'rent'], true)) throw new AppError('Choose a type.'); $a = cents($_POST['amount'] ?? ''); if ($a <= 0 || trim((string)$_POST['name']) === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$_POST['next_due'])) throw new AppError('Fill in name, amount and next due date.'); q('INSERT INTO recurring_items (user_id,kind,name,merchant,amount,frequency,next_due,category) VALUES (?,?,?,?,?,?,?,?)', [$uid, $k, mb_substr(trim($_POST['name']), 0, 100), mb_substr(trim((string)$_POST['merchant']), 0, 100), dec($a), in_array($_POST['frequency'], ['weekly', 'monthly', 'yearly'], true) ? $_POST['frequency'] : 'monthly', $_POST['next_due'], $k === 'income' ? 'income' : ($k === 'subscription' ? 'entertainment' : 'bills')]); return 'Added.'; });
handle('rec_status', function () use ($uid) { $to = $_POST['to'] ?? ''; if (!in_array($to, ['active', 'paused', 'cancelled'], true)) throw new AppError('Invalid.'); q("UPDATE recurring_items SET status=? WHERE id=? AND user_id=? AND status<>'cancelled'", [$to, (int)$_POST['id'], $uid]); return 'Updated.'; });
handle('rec_pay', function () use ($uid) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); $r = Pay::payBill($uid, (int)$_POST['id'], idem_key(), ($_POST['override'] ?? '') === '1'); return 'Bill paid (simulated external payee). Reference ' . $r['ref']; });
echo page_head('Recurring', 'Bills, subscriptions, rent and income on one calendar. Reminders appear 3 days before a due date.');
$items = rows("SELECT * FROM recurring_items WHERE user_id=? AND status<>'cancelled' ORDER BY status, next_due", [$uid]); $rows = []; $seen = [];
foreach ($items as $i) { $key = strtolower($i['merchant'] ?: $i['name']) . '|' . $i['amount']; $dup = $i['kind'] !== 'income' && $i['status'] === 'active' && isset($seen[$key]); if ($i['kind'] !== 'income' && $i['status'] === 'active') $seen[$key] = 1;
  $act = form_start('rec_status', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$i['id'] . '"><input type="hidden" name="to" value="' . ($i['status'] === 'active' ? 'paused' : 'active') . '">' . btn($i['status'] === 'active' ? 'Pause' : 'Resume', 'secondary sm') . '</form> ' . form_start('rec_status', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$i['id'] . '"><input type="hidden" name="to" value="cancelled">' . btn('Cancel', 'secondary sm', 'submit', 'onclick="return confirm(\'Cancel this item?\')"') . '</form>';
  if ($i['kind'] !== 'income' && $i['status'] === 'active') $act = form_start('rec_pay', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$i['id'] . '"><div class="row"><input name="pin" type="password" inputmode="numeric" maxlength="6" placeholder="PIN" required style="min-width:80px" aria-label="PIN"><label class="fixed" style="margin:0;font-weight:400"><input type="checkbox" name="override" value="1"> pay anyway</label>' . btn('Pay now', 'sm') . '</div></form>' . $act;
  $rows[] = [e(ucfirst($i['kind'])), e($i['name']) . ($dup ? '<div class="hint neg">Possible duplicate: same payee and amount as another active item</div>' : ''), '<span class="' . ($i['kind'] === 'income' ? 'pos' : '') . '">' . mny($i['amount'], $i['currency']) . '</span> <span class="hint">/' . e($i['frequency']) . '</span>', e(fdate($i['next_due'], false)), badge($i['status']), $act]; }
echo card('Your recurring items', tbl(['Type', 'Name', ['Amount', 'num'], 'Next due', 'Status', ''], $rows, 'Nothing scheduled yet.'));
$cal = []; foreach (Cash::safe($uid, 30)['bills'] as $b) $cal[$b['date']][] = '- ' . $b['name'] . ' ' . dec($b['amount_c']); foreach (Cash::safe($uid, 30)['income'] as $b) $cal[$b['date']][] = '+ ' . $b['name'] . ' ' . dec($b['amount_c']); ksort($cal); $cb = '';
foreach ($cal as $d => $ls) $cb .= '<div class="row" style="padding:6px 0;border-top:1px solid var(--line)"><div class="fixed" style="width:110px"><strong>' . e(fdate($d, false)) . '</strong></div><div>' . implode('<br>', array_map('e', $ls)) . '</div></div>';
$dups = rows("SELECT * FROM risk_alerts WHERE user_id=? AND alert_type='duplicate_expense' ORDER BY id DESC LIMIT 3", [$uid]); $dm = ''; foreach ($dups as $d) $dm .= '<div class="alert warn">' . e($d['message']) . '</div>';
echo '<div style="height:16px"></div><div class="grid g2">' . card('Next 30 days calendar', $cb ?: empty_state('Nothing due in the next 30 days.', 'calendar') . '') . card('Add a recurring item', form_start('rec_add') . select('Type', 'kind', ['bill' => 'Bill', 'subscription' => 'Subscription', 'rent' => 'Rent', 'income' => 'Known income'], 'bill') . field('Name', 'name', 'text', '', 'required maxlength="100"') . field('Merchant or payer', 'merchant', 'text', '', 'maxlength="100"') . '<div class="row">' . field('Amount (BDT)', 'amount', 'text', '', 'required inputmode="decimal"') . select('Repeats', 'frequency', ['monthly' => 'Monthly', 'weekly' => 'Weekly', 'yearly' => 'Yearly'], 'monthly') . '</div>' . field('Next due date', 'next_due', 'date', date('Y-m-d', strtotime('+7 days')), 'required') . btn('Add') . '</form>' . $dm) . '</div>';
